<div class="page-title-row"><div><span class="eyebrow">NHÌN LẠI VÀ LÊN KẾ HOẠCH</span><h1>Thống kê thư viện</h1><p>Các chỉ số hoạt động dựa trên dữ liệu hiện có.</p></div><a class="button button-outline" href="<?= e(url('/admin/statistics/export?from=' . rawurlencode($dateFrom) . '&to=' . rawurlencode($dateTo) . '&status=' . rawurlencode($reportStatus))) ?>">Tải báo cáo CSV UTF-8</a></div>
<form class="filter-bar staff-filter" method="get" action="<?= e(url('/admin/statistics')) ?>"><label>Ngày bắt đầu<input type="date" name="from" value="<?= e($dateFrom) ?>" required></label><label>Ngày kết thúc<input type="date" name="to" value="<?= e($dateTo) ?>" required></label><label>Trạng thái<select name="status"><option value="">Tất cả</option><option value="borrowed"<?= selected($reportStatus, 'borrowed') ?>>Đang mượn</option><option value="overdue"<?= selected($reportStatus, 'overdue') ?>>Quá hạn</option><option value="returned"<?= selected($reportStatus, 'returned') ?>>Đã trả</option></select></label><button class="button button-primary" type="submit">Lọc báo cáo</button></form>
<section class="metrics-grid statistics-metrics"><?php foreach ([['Đầu sách', $bookMetrics['title_count'] ?? 0], ['Bản sách', $bookMetrics['copy_count'] ?? 0], ['Đang cho mượn', $loanMetrics['active_count'] ?? 0], ['Độc giả hoạt động', $readerMetrics['reader_count'] ?? 0]] as [$label,$value]): ?><article class="metric-card"><span class="metric-label"><?= e($label) ?></span><strong><?= number_format((int) $value) ?></strong></article><?php endforeach; ?></section>
<div class="dashboard-columns">
  <section class="panel"><div class="panel-heading"><div><span class="eyebrow">6 THÁNG GẦN NHẤT</span><h2>Lượt mượn theo tháng</h2></div></div>
    <?php if ($monthly): ?><?php $max = max(1, ...array_map(static fn($item) => (int) $item['loan_count'], $monthly)); ?><div class="bar-chart" role="img" aria-label="Biểu đồ lượt mượn theo tháng"><?php foreach ($monthly as $item): ?><div class="bar-column"><strong><?= (int) $item['loan_count'] ?></strong><span style="height:<?= max(4, round((int) $item['loan_count'] * 150 / $max)) ?>px"></span><small><?= e(date('m/Y', strtotime($item['month_key'] . '-01'))) ?></small></div><?php endforeach; ?></div><?php else: ?><div class="empty-inline">Chưa có dữ liệu lượt mượn để hiển thị.</div><?php endif; ?>
  </section>
  <section class="panel"><div class="panel-heading"><div><span class="eyebrow">PHÂN BỐ ĐẦU SÁCH</span><h2>Thể loại nổi bật</h2></div></div><?php if ($categoryStats): ?><div class="category-stat-list"><?php $maxTitles = max(1, ...array_map(static fn($item) => (int) $item['title_count'], $categoryStats)); foreach ($categoryStats as $category): ?><div><div><strong><?= e($category['name']) ?></strong><span><?= (int) $category['title_count'] ?> tựa · <?= (int) $category['copy_count'] ?> bản</span></div><div class="progress-track"><span style="width:<?= min(100, round((int) $category['title_count'] * 100 / $maxTitles)) ?>%"></span></div></div><?php endforeach; ?></div><?php else: ?><div class="empty-inline">Chưa có thể loại sách.</div><?php endif; ?></section>
</div>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">ĐỘC GIẢ LỰA CHỌN</span><h2>Sách được mượn nhiều</h2></div></div><?php if ($popularBooks): ?><div class="table-scroll"><table><thead><tr><th>Tựa sách</th><th>Tác giả</th><th>Thể loại</th><th>Bản có thể mượn</th></tr></thead><tbody><?php foreach ($popularBooks as $book): ?><tr><td><a class="table-link" href="<?= e(url('/book/' . $book['id'])) ?>"><?= e($book['title']) ?></a></td><td><?= e($book['author']) ?></td><td><?= e($book['category_name'] ?? '—') ?></td><td><?= (int) $book['available_copies'] ?> / <?= (int) $book['total_copies'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-inline">Chưa có dữ liệu.</div><?php endif; ?></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">CHI TIẾT THEO KHOẢNG NGÀY</span><h2>Danh sách lượt mượn</h2></div><span class="muted"><?= count($reportRows) ?> dòng xem trước</span></div><?php if ($reportRows): ?><div class="table-scroll"><table><thead><tr><th>Phiếu / độc giả</th><th>Sách / bản sao</th><th>Ngày mượn</th><th>Hạn trả</th><th>Ngày trả</th><th>Trạng thái</th><th>Dư phí</th></tr></thead><tbody><?php foreach ($reportRows as $row): $outstanding = max(0, (float) $row['charged_amount'] - (float) $row['paid_amount'] - (float) $row['waived_amount']); ?><tr><td><strong><?= e($row['loan_code']) ?></strong><small><?= e($row['card_number']) ?> · <?= e($row['full_name']) ?></small></td><td><strong><?= e($row['title']) ?></strong><small><?= e($row['book_code']) ?> · <?= e($row['copy_code']) ?></small></td><td><?= e(format_date($row['borrowed_at'])) ?></td><td><?= e(format_date($row['due_date'])) ?></td><td><?= e(format_date($row['returned_at'])) ?></td><td><span class="status-pill <?= e($row['item_status']) ?>"><?= ['returned' => 'Đã trả', 'overdue' => 'Quá hạn', 'borrowed' => 'Đang mượn'][$row['item_status']] ?? e($row['item_status']) ?></span></td><td><?= number_format($outstanding, 0, ',', '.') ?>đ</td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-inline">Không có lượt mượn trong bộ lọc đã chọn.</div><?php endif; ?></section>

<?php foreach (['inventory'=>['Tồn kho',$inventoryReport], 'fines'=>['Phí phạt',$fineReport]] as $kind=>[$label,$rows]): ?>
<section class="panel"><div class="panel-heading"><div><h2>Báo cáo <?= e($label) ?></h2><p>50 dòng xem trước; CSV tối đa 10.000 dòng.</p></div><a class="button button-outline" href="<?= e(url('/admin/statistics/export?kind='.$kind)) ?>">Xuất CSV <?= e($label) ?></a></div><div class="table-scroll"><table><thead><tr><?php foreach(\Library\Repositories\ReportRepository::headers($kind) as $heading): ?><th><?= e($heading) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $cell): ?><td><?= e($cell ?? '—') ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="10">Chưa có dữ liệu.</td></tr><?php endif; ?></tbody></table></div></section>
<?php endforeach; ?>
